operations.old:
const expected = runInteraction(previous, event.方式, event);
const isFestival = ['festivalStart','festivalEnd'].includes(JSON.parse(event.方式).kind);
if (isFestival && JSON.stringify(submitted) === JSON.stringify(before)) {
  // The model appends facts; the domain, not the model, derives lifecycle flags.
  candidate.生活 = expected;
} else if (JSON.stringify(expected) !== JSON.stringify(submitted)) fail('生活互动变化超出允许范围');

operations.new:
const current = { ...previous, 环境: { ...previous.环境, 天数: candidate.环境.天数 }, 生活: before };
const expected = runInteraction(current, event.方式, event);
if (JSON.stringify(submitted) === JSON.stringify(before)) {
  // Facts identify the bounded interaction; the domain derives its state.
  candidate.生活 = expected;
} else if (JSON.stringify(expected) !== JSON.stringify(submitted)) fail('生活互动变化超出允许范围');
